import assert from 'node:assert/strict';
import test from 'node:test';
import {collection} from './subject.mjs';
function generatedInput(seed){return {name:((seed*1664525+1013904223)>>>0).toString(16),enabled:true};}
test('post/get preserves generated input fields',()=>{const api=collection();const input=generatedInput(42);const id=api.post(input);assert.deepEqual(api.get(id),input);});

import assert from 'node:assert/strict';
import test from 'node:test';
import {namePolicy,postName} from './subject.mjs';
for(const value of ['alice','ALICE'])test('policy accepts '+value,()=>assert.deepEqual(namePolicy(value),{tag:'Accepted'}));
for(const value of ['','alice1'])test('policy rejects '+value,()=>assert.deepEqual(namePolicy(value),{tag:'Invalid'}));
test('adapter maps accepted outcome',()=>assert.equal(postName('alice').status,201));
test('adapter maps invalid outcome',()=>assert.equal(postName('').status,400));
